181| object ApiRateLimiter {
182|     private val requestTimes = ConcurrentHashMap<String, Long>()
183|     private val limits = mapOf(
184|         "default" to RateLimit(60, 60000),
185|         "fast" to RateLimit(1000, 60000)
186|     )
187|     
188|     data class RateLimit(val maxRequests: Int, val windowMs: Long)
189|     
190|     fun canMakeRequest(key: String = "default"): Boolean {
191|         val limit = limits[key] ?: limits["default"]!!
192|         val now = System.currentTimeMillis()
193|         val lastRequest = requestTimes[key]
194|         
195|         return if (lastRequest == null) {
196|             true
197|         } else if (now - lastRequest > limit.windowMs) {
198|             true
199|         } else {
200|             requestTimes.values.count { it > now - limit.windowMs } < limit.maxRequests
201|         }
202|     }
203|     
204|     fun recordRequest(key: String = "default") {
205|         requestTimes[key] = System.currentTimeMillis()
206|     }
207|     
208|     suspend fun waitIfNeeded(key: String = "default") {
209|         while (!canMakeRequest(key)) {
210|             delay(100)
211|         }
212|         recordRequest(key)
213|     }
